//! Shared bench inputs.
//!
//! Inputs are generated by encoding frames with this crate, so the decode benchmarks operate on valid payloads with
//! the same shapes as the encode benchmarks.

#![allow(dead_code)]

use redis_protocol::{
  resp2::types::{OwnedFrame as Resp2Frame, Resp2Frame as _},
  resp3::types::{OwnedFrame as Resp3Frame, Resp3Frame as _},
};

/// Deterministic printable payload of `len` bytes.
pub fn payload(len: usize) -> Vec<u8> {
  (0 .. len).map(|i| b'a' + (i % 26) as u8).collect()
}

/// Named RESP2 frames covering common response shapes.
pub fn resp2_frames() -> Vec<(&'static str, Resp2Frame)> {
  let bulk = |len| Resp2Frame::BulkString(payload(len));
  let array = |len: usize, null_every: usize, str_len: usize| {
    Resp2Frame::Array(
      (0 .. len)
        .map(|i| {
          if null_every > 0 && (i + 1) % null_every == 0 {
            Resp2Frame::Null
          } else {
            bulk(str_len)
          }
        })
        .collect(),
    )
  };
  let mixed = Resp2Frame::Array(
    (0 .. 100)
      .map(|i| match i % 4 {
        0 => Resp2Frame::SimpleString(b"OK".to_vec()),
        1 => Resp2Frame::Integer(i as i64 * 1_000_003),
        2 => bulk(24),
        _ => Resp2Frame::Null,
      })
      .collect(),
  );
  let mut nested = Resp2Frame::BulkString(payload(16));
  for _ in 0 .. 32 {
    nested = Resp2Frame::Array(vec![nested, Resp2Frame::Integer(1)]);
  }

  vec![
    ("bulkstring/16B", bulk(16)),
    ("bulkstring/1KiB", bulk(1024)),
    ("bulkstring/64KiB", bulk(64 * 1024)),
    ("bulkstring/1MiB", bulk(1024 * 1024)),
    ("array/10x1KiB", array(10, 0, 1024)),
    ("array/100x32B", array(100, 0, 32)),
    ("array/1000x32B", array(1000, 0, 32)),
    ("array/1000x32B_half_nulls", array(1000, 2, 32)),
    ("array/100_mixed", mixed),
    ("array/nested_32", nested),
  ]
}

/// Named RESP3 frames covering common response shapes.
pub fn resp3_frames() -> Vec<(&'static str, Resp3Frame)> {
  let blob = |len| Resp3Frame::BlobString {
    data:       payload(len),
    attributes: None,
  };
  let array = |len: usize, str_len: usize| Resp3Frame::Array {
    data:       (0 .. len).map(|_| blob(str_len)).collect(),
    attributes: None,
  };
  let map = Resp3Frame::Map {
    data:       (0 .. 100)
      .map(|i| {
        (
          Resp3Frame::BlobString {
            data:       format!("field:{i}").into_bytes(),
            attributes: None,
          },
          blob(32),
        )
      })
      .collect(),
    attributes: None,
  };
  let mixed = Resp3Frame::Array {
    data:       (0 .. 100)
      .map(|i| match i % 5 {
        0 => Resp3Frame::SimpleString {
          data:       b"OK".to_vec(),
          attributes: None,
        },
        1 => Resp3Frame::Number {
          data:       i as i64 * 1_000_003,
          attributes: None,
        },
        2 => Resp3Frame::Double {
          data:       i as f64 * 1.5,
          attributes: None,
        },
        3 => blob(24),
        _ => Resp3Frame::Null,
      })
      .collect(),
    attributes: None,
  };
  let mut nested = blob(16);
  for _ in 0 .. 32 {
    nested = Resp3Frame::Array {
      data:       vec![nested, Resp3Frame::Number {
        data:       1,
        attributes: None,
      }],
      attributes: None,
    };
  }

  vec![
    ("blobstring/16B", blob(16)),
    ("blobstring/1KiB", blob(1024)),
    ("blobstring/64KiB", blob(64 * 1024)),
    ("blobstring/1MiB", blob(1024 * 1024)),
    ("array/10x1KiB", array(10, 1024)),
    ("array/100x32B", array(100, 32)),
    ("array/1000x32B", array(1000, 32)),
    ("map/100x32B", map),
    ("array/100_mixed", mixed),
    ("array/nested_32", nested),
  ]
}

pub fn encode_resp2(frame: &Resp2Frame) -> Vec<u8> {
  let mut buf = vec![0; frame.encode_len(false)];
  let len = redis_protocol::resp2::encode::encode(&mut buf, frame, false).unwrap();
  buf.truncate(len);
  buf
}

pub fn encode_resp3(frame: &Resp3Frame) -> Vec<u8> {
  let mut buf = vec![0; frame.encode_len(false)];
  let len = redis_protocol::resp3::encode::complete::encode(&mut buf, frame, false).unwrap();
  buf.truncate(len);
  buf
}
